// C#
class Konto
{
    private double stand;
    public void Einzahlen(double b)
    { stand += b; }
    public double GetStand()
    { return stand; }
}

# Python
class Konto:
    def __init__(self):
        self.__stand = 0.0
    def einzahlen(self, b):
        self.__stand += b
    def get_stand(self):
        return self.__stand

